files.content:
:root {
  --bg: #1a1c2c;
  --card: #29366f;
  --accent: #ffcd75;
  --accent-2: #38b764;
  --text: #f4f4f4;
  --muted: #94b0c2;
  --border: #0f1020;
  --shadow: #0b0c16;
  font-size: 16px;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
  background-color: var(--bg);
  background-image:
    linear-gradient(45deg, rgba(255,255,255,0.03) 25%, transparent 25%, transparent 75%, rgba(255,255,255,0.03) 75%),
    linear-gradient(45deg, rgba(255,255,255,0.03) 25%, transparent 25%, transparent 75%, rgba(255,255,255,0.03) 75%);
  background-size: 16px 16px;
  background-position: 0 0, 8px 8px;
  font-family: ui-monospace, 'Courier New', monospace;
  color: var(--text);
}

.card {
  width: 100%;
  max-width: 420px;
  background: var(--card);
  border: 4px solid var(--border);
  box-shadow: 8px 8px 0 var(--shadow);
  padding: 28px 24px 24px;
  text-align: center;
  image-rendering: pixelated;
}

.pixel-title {
  margin: 0 0 20px;
  font-size: 1.25rem;
  letter-spacing: 2px;
  color: var(--accent);
  text-shadow: 2px 2px 0 var(--border);
}

.mode-switch {
  display: flex;
  gap: 10px;
  margin-bottom: 18px;
}

.mode-btn {
  flex: 1;
  font-family: inherit;
  font-size: 0.85rem;
  padding: 10px 6px;
  color: var(--muted);
  background: var(--bg);
  border: 3px solid var(--border);
  cursor: pointer;
  letter-spacing: 1px;
}

.mode-btn:hover { color: var(--text); background: #23263a; }
.mode-btn:focus-visible { outline: 3px solid var(--accent); outline-offset: 2px; }
.mode-btn:active { transform: translateY(2px); }
.mode-btn.active { color: var(--bg); background: var(--accent); border-color: var(--accent); }

.mode-label {
  font-size: 0.9rem;
  color: var(--muted);
  letter-spacing: 1px;
  margin-bottom: 6px;
}

.countdown {
  font-size: clamp(3.5rem, 22vw, 6rem);
  font-weight: 700;
  line-height: 1;
  letter-spacing: 4px;
  color: var(--text);
  text-shadow: 4px 4px 0 var(--border);
  margin: 8px 0 24px;
  font-variant-numeric: tabular-nums;
}

.controls {
  display: flex;
  gap: 12px;
  margin-bottom: 18px;
}

.btn {
  flex: 1;
  font-family: inherit;
  font-size: 1rem;
  padding: 14px 10px;
  color: var(--text);
  background: var(--bg);
  border: 3px solid var(--border);
  box-shadow: 4px 4px 0 var(--shadow);
  cursor: pointer;
  letter-spacing: 2px;
}

.btn:hover { background: #23263a; }
.btn:focus-visible { outline: 3px solid var(--accent); outline-offset: 2px; }
.btn:active { transform: translate(2px, 2px); box-shadow: 2px 2px 0 var(--shadow); }
.btn.primary { color: var(--bg); background: var(--accent-2); border-color: var(--accent-2); }
.btn.primary:hover { background: #2f9e55; }

.hint {
  margin: 0;
  font-size: 0.8rem;
  color: var(--muted);
}

@media (max-width: 380px) {
  body { padding: 12px; }
  .card { padding: 20px 16px; box-shadow: 5px 5px 0 var(--shadow); }
  .pixel-title { font-size: 1.05rem; letter-spacing: 1px; }
  .mode-btn { font-size: 0.75rem; padding: 9px 4px; }
  .btn { font-size: 0.9rem; padding: 12px 8px; letter-spacing: 1px; }
}

(function () {
  'use strict';

  var WORK = 25 * 60;
  var BREAK = 5 * 60;

  var state = {
    mode: 'work',
    remaining: WORK,
    running: false,
    endAt: 0,
    tick: null
  };

  var countdownEl = document.getElementById('countdown');
  var modeLabelEl = document.getElementById('mode-label');
  var startPauseBtn = document.getElementById('start-pause');
  var resetBtn = document.getElementById('reset');
  var workBtn = document.getElementById('mode-work');
  var breakBtn = document.getElementById('mode-break');

  function format(sec) {
    var m = Math.floor(sec / 60);
    var s = sec % 60;
    return (m < 10 ? '0' : '') + m + ':' + (s < 10 ? '0' : '') + s;
  }

  function render() {
    countdownEl.textContent = format(state.remaining);
    startPauseBtn.textContent = state.running ? 'PAUSE' : 'START';
    startPauseBtn.setAttribute('aria-label', state.running ? 'Pause timer' : 'Start timer');
    modeLabelEl.textContent = state.mode === 'work' ? 'Work session' : 'Break session';
  }

  function setMode(mode) {
    state.mode = mode;
    state.running = false;
    clearInterval(state.tick);
    state.tick = null;
    state.remaining = mode === 'work' ? WORK : BREAK;
    workBtn.classList.toggle('active', mode === 'work');
    breakBtn.classList.toggle('active', mode === 'break');
    workBtn.setAttribute('aria-pressed', mode === 'work' ? 'true' : 'false');
    breakBtn.setAttribute('aria-pressed', mode === 'break' ? 'true' : 'false');
    render();
  }

  function tickFn() {
    var left = Math.round((state.endAt - Date.now()) / 1000);
    if (left < 0) left = 0;
    state.remaining = left;
    render();
    if (left <= 0) {
      clearInterval(state.tick);
      state.tick = null;
      state.running = false;
      // Auto switch mode
      if (state.mode === 'work') {
        setMode('break');
      } else {
        setMode('work');
      }
    }
  }

  function start() {
    if (state.running) return;
    if (state.remaining <= 0) {
      state.remaining = state.mode === 'work' ? WORK : BREAK;
    }
    state.endAt = Date.now() + state.remaining * 1000;
    state.running = true;
    state.tick = setInterval(tickFn, 250);
    render();
  }

  function pause() {
    if (!state.running) return;
    clearInterval(state.tick);
    state.tick = null;
    state.running = false;
    state.remaining = Math.max(0, Math.round((state.endAt - Date.now()) / 1000));
    render();
  }

  function toggle() {
    if (state.running) {
      pause();
    } else {
      start();
    }
  }

  function reset() {
    clearInterval(state.tick);
    state.tick = null;
    state.running = false;
    state.remaining = state.mode === 'work' ? WORK : BREAK;
    render();
  }

  startPauseBtn.addEventListener('click', toggle);
  resetBtn.addEventListener('click', reset);
  workBtn.addEventListener('click', function () { setMode('work'); });
  breakBtn.addEventListener('click', function () { setMode('break'); });

  document.addEventListener('keydown', function (e) {
    if (e.target.tagName === 'INPUT' || e.target.tagName === 'TEXTAREA') return;
    if (e.code === 'Space') {
      e.preventDefault();
      toggle();
    } else if (e.key === 'r' || e.key === 'R') {
      reset();
    }
  });

  render();
})();
